-- lease_saps_bill 117..2922
WITH q AS (SELECT p.id,p.bill_no AS business_key,p.tenant_code,p.total_amount,p.paid_amount,p.unpaid_amount,COALESCE(p.red_amount,0) AS red_amount,p.settlement_status AS status,(SELECT COUNT(*) FROM lease_saps.bill_fee_detail d WHERE d.bill_no=p.bill_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS fee_n,(SELECT COALESCE(SUM(total_amount),0) FROM lease_saps.bill_fee_detail d WHERE d.bill_no=p.bill_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS fee_total,(SELECT COALESCE(SUM(paid_amount),0) FROM lease_saps.bill_fee_detail d WHERE d.bill_no=p.bill_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS fee_paid,(SELECT COALESCE(SUM(unpaid_amount),0) FROM lease_saps.bill_fee_detail d WHERE d.bill_no=p.bill_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS fee_unpaid,(SELECT COALESCE(SUM(pay_amount),0) FROM lease_saps.customer_bill_pay_detail d WHERE d.bill_no=p.bill_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS pay_total,(SELECT COUNT(*) FROM lease_saps.customer_bill d WHERE d.bill_no=p.bill_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicates FROM lease_saps.customer_bill p WHERE p.id BETWEEN 117 AND 2922 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN NOT(total_amount <=> fee_total) THEN 1 ELSE 0 END),0) AS TOTAL_DETAILS_n,COALESCE(SUM(CASE WHEN NOT(total_amount <=> fee_total) THEN ABS(total_amount-fee_total) ELSE 0 END),0) AS TOTAL_DETAILS_diff,COALESCE(SUM(CASE WHEN total_amount<>0 AND fee_n=0 THEN 1 ELSE 0 END),0) AS MISSING_DETAILS_n,COALESCE(SUM(CASE WHEN total_amount<>0 AND fee_n=0 THEN ABS(total_amount) ELSE 0 END),0) AS MISSING_DETAILS_diff,COALESCE(SUM(CASE WHEN total_amount IS NULL OR paid_amount IS NULL OR unpaid_amount IS NULL OR NOT(total_amount <=> paid_amount+unpaid_amount+red_amount) THEN 1 ELSE 0 END),0) AS BALANCE_n,COALESCE(SUM(CASE WHEN total_amount IS NULL OR paid_amount IS NULL OR unpaid_amount IS NULL OR NOT(total_amount <=> paid_amount+unpaid_amount+red_amount) THEN ABS(total_amount-paid_amount-unpaid_amount-red_amount) ELSE 0 END),0) AS BALANCE_diff,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> pay_total) THEN 1 ELSE 0 END),0) AS PAID_SETTLEMENT_n,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> pay_total) THEN ABS(paid_amount-pay_total) ELSE 0 END),0) AS PAID_SETTLEMENT_diff,COALESCE(SUM(CASE WHEN status=1 AND (unpaid_amount IS NULL OR unpaid_amount<>0) THEN 1 ELSE 0 END),0) AS SETTLED_UNPAID_n,COALESCE(SUM(CASE WHEN status=1 AND (unpaid_amount IS NULL OR unpaid_amount<>0) THEN ABS(unpaid_amount) ELSE 0 END),0) AS SETTLED_UNPAID_diff,COALESCE(SUM(CASE WHEN duplicates>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicates>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> fee_paid) THEN 1 ELSE 0 END),0) AS PAID_DETAILS_n,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> fee_paid) THEN ABS(paid_amount-fee_paid) ELSE 0 END),0) AS PAID_DETAILS_diff,COALESCE(SUM(CASE WHEN NOT(unpaid_amount <=> fee_unpaid) THEN 1 ELSE 0 END),0) AS UNPAID_DETAILS_n,COALESCE(SUM(CASE WHEN NOT(unpaid_amount <=> fee_unpaid) THEN ABS(unpaid_amount-fee_unpaid) ELSE 0 END),0) AS UNPAID_DETAILS_diff FROM q LIMIT 1;

