 ABS(total_amount) ELSE 0 END),0) AS MISSING_DETAILS_diff,COALESCE(SUM(CASE WHEN total_amount IS NULL OR paid_amount IS NULL OR unpaid_amount IS NULL OR NOT(total_amount <=> paid_amount+unpaid_amount+red_amount) THEN 1 ELSE 0 END),0) AS BALANCE_n,COALESCE(SUM(CASE WHEN total_amount IS NULL OR paid_amount IS NULL OR unpaid_amount IS NULL OR NOT(total_amount <=> paid_amount+unpaid_amount+red_amount) THEN ABS(total_amount-paid_amount-unpaid_amount-red_amount) ELSE 0 END),0) AS BALANCE_diff,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> pay_total) THEN 1 ELSE 0 END),0) AS PAID_SETTLEMENT_n,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> pay_total) THEN ABS(paid_amount-pay_total) ELSE 0 END),0) AS PAID_SETTLEMENT_diff,COALESCE(SUM(CASE WHEN status=4 AND (unpaid_amount IS NULL OR unpaid_amount<>0) THEN 1 ELSE 0 END),0) AS SETTLED_UNPAID_n,COALESCE(SUM(CASE WHEN status=4 AND (unpaid_amount IS NULL OR unpaid_amount<>0) THEN ABS(unpaid_amount) ELSE 0 END),0) AS SETTLED_UNPAID_diff,COALESCE(SUM(CASE WHEN duplicates>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicates>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> fee_paid) THEN 1 ELSE 0 END),0) AS PAID_DETAILS_n,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> fee_paid) THEN ABS(paid_amount-fee_paid) ELSE 0 END),0) AS PAID_DETAILS_diff,COALESCE(SUM(CASE WHEN NOT(unpaid_amount <=> fee_unpaid) THEN 1 ELSE 0 END),0) AS UNPAID_DETAILS_n,COALESCE(SUM(CASE WHEN NOT(unpaid_amount <=> fee_unpaid) THEN ABS(unpaid_amount-fee_unpaid) ELSE 0 END),0) AS UNPAID_DETAILS_diff FROM q LIMIT 1;

-- lease_saps_order 23..20022
WITH q AS (SELECT p.id,p.order_no AS business_key,p.status,p.sub_type,p.transaction_mode,p.pay_amount,p.transaction_amount,p.settle_amount,p.recharge_amount,p.discount_amount,(SELECT COUNT(*) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_n,(SELECT COALESCE(SUM(pay_amount),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_requested,(SELECT COALESCE(SUM(CASE WHEN status=4 THEN transaction_amount ELSE 0 END),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_actual,(SELECT COALESCE(SUM(CASE WHEN status=4 THEN settle_amount ELSE 0 END),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_settle,(SELECT COALESCE(SUM(CASE WHEN status=4 THEN recharge_amount ELSE 0 END),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_recharge,(SELECT COUNT(*) FROM lease_saps.customer_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicates FROM lease_saps.customer_order p WHERE p.id BETWEEN 23 AND 20022 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN detail_n=0 THEN 1 ELSE 0 END),0) AS MISSING_TRANSACTION_n,COALESCE(SUM(CASE WHEN detail_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_TRANSACTION_diff,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> detail_requested) THEN 1 ELSE 0 END),0) AS REQUESTED_DETAILS_n,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> detail_requested) THEN ABS(pay_amount-detail_requested) ELSE 0 END),0) AS REQUESTED_DETAILS_diff,COALESCE(SUM(CASE WHEN status=4 AND NOT(transaction_amount <=> detail_actual) THEN 1 ELSE 0 END),0) AS ACTUAL_DETAILS_n,COALESCE(SUM(CASE WHEN status=4 AND NOT(transaction_amount <=> detail_actual) THEN ABS(transaction_amount-detail_actual) ELSE 0 END),0) AS ACTUAL_DETAILS_diff,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(settle_amount <=> detail_settle) THEN 1 ELSE 0 END),0) AS SETTLE_DETAILS_n,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(settle_amount <=> detail_settle) THEN ABS(settle_amount-detail_settle) ELSE 0 END),0) AS SETTLE_DETAILS_diff,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(recharge_amount <=> detail_recharge) THEN 1 ELSE 0 END),0) AS RECHARGE_DETAILS_n,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(recharge_amount <=> detail_recharge) THEN ABS(recharge_amount-detail_recharge) ELSE 0 END),0) AS RECHARGE_DETAILS_diff,COALESCE(SUM(CASE WHEN duplicates>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicates>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff FROM q LIMIT 1;

