-- ol_order_payable 1..3551
WITH q AS (SELECT p.id,p.order_no AS business_key,p.order_status,p.amount,p.paid_amount,p.purchase_order_no,p.batch_no,(SELECT COALESCE(SUM(d.pay_amount),0) FROM ol_order.payment_order_paydetail d WHERE d.pay_order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_paid,(SELECT COUNT(*) FROM ol_order.payment_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicate_n,(SELECT COUNT(*) FROM ol_order.purchase_order d WHERE d.order_no=p.purchase_order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS source_n,(SELECT MIN(d.purchase_price) FROM ol_order.purchase_order d WHERE d.order_no=p.purchase_order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS source_amount FROM ol_order.payment_order p WHERE p.id BETWEEN 1 AND 3551 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> detail_paid) THEN 1 ELSE 0 END),0) AS PAID_DETAIL_n,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> detail_paid) THEN ABS(paid_amount-detail_paid) ELSE 0 END),0) AS PAID_DETAIL_diff,COALESCE(SUM(CASE WHEN order_status='paid' AND NOT(amount <=> paid_amount) THEN 1 ELSE 0 END),0) AS PAID_STATUS_n,COALESCE(SUM(CASE WHEN order_status='paid' AND NOT(amount <=> paid_amount) THEN ABS(amount-paid_amount) ELSE 0 END),0) AS PAID_STATUS_diff,COALESCE(SUM(CASE WHEN duplicate_n>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicate_n>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff,COALESCE(SUM(CASE WHEN source_n=0 THEN 1 ELSE 0 END),0) AS SOURCE_MISSING_n,COALESCE(SUM(CASE WHEN source_n=0 THEN ABS(amount) ELSE 0 END),0) AS SOURCE_MISSING_diff,COALESCE(SUM(CASE WHEN COALESCE(batch_no,'')='' AND NOT(amount <=> source_amount) THEN 1 ELSE 0 END),0) AS SOURCE_AMOUNT_n,COALESCE(SUM(CASE WHEN COALESCE(batch_no,'')='' AND NOT(amount <=> source_amount) THEN ABS(amount-source_amount) ELSE 0 END),0) AS SOURCE_AMOUNT_diff FROM q LIMIT 1;

-- lease_finance_payable 2..67
WITH q AS (SELECT p.id,p.payment_no AS business_key,p.status,p.payment_result,p.amount,p.pay_amount,p.payment_serial_no,(SELECT COUNT(*) FROM lease_finance.payment_order d WHERE d.payment_no=p.payment_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicate_n FROM lease_finance.payment_order p WHERE p.id BETWEEN 2 AND 67 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN status=40 AND NOT(amount <=> pay_amount) THEN 1 ELSE 0 END),0) AS PAID_STATUS_n,COALESCE(SUM(CASE WHEN status=40 AND NOT(amount <=> pay_amount) THEN ABS(amount-pay_amount) ELSE 0 END),0) AS PAID_STATUS_diff,COALESCE(SUM(CASE WHEN duplicate_n>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicate_n>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff,COALESCE(SUM(CASE WHEN status=40 AND NOT(payment_result <=> 4) THEN 1 ELSE 0 END),0) AS PAYMENT_STATE_n,COALESCE(SUM(CASE WHEN status=40 AND NOT(payment_result <=> 4) THEN ABS(0) ELSE 0 END),0) AS PAYMENT_STATE_diff FROM q LIMIT 1;

-- lease_saps_bill_settlement 31..1696
WITH q AS (SELECT p.id,p.serial_no AS business_key,p.bill_no AS document_no,p.order_no,p.trans_no,p.pay_amount,p.is_reverse,(SELECT COALESCE(SUM(d.paid_amount),0) FROM lease_saps.customer_bill_pay_subject_detail d WHERE d.pay_detail_serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS subject_total,(SELECT COUNT(*) FROM lease_saps.customer_bill d WHERE d.bill_no=p.bill_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS parent_n,(SELECT COUNT(*) FROM lease_saps.customer_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS order_n,(SELECT COUNT(*) FROM lease_saps.customer_transaction d WHERE d.serial_no=p.trans_no AND d.order_no=p.order_no AND d.status=4 AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS transaction_n FROM lease_saps.customer_bill_pay_detail p WHERE p.id BETWEEN 31 AND 1696 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> subject_total) THEN 1 ELSE 0 END),0) AS SUBJECT_SUM_n,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> subject_total) THEN ABS(pay_amount-subject_total) ELSE 0 END),0) AS SUBJECT_SUM_diff,COALESCE(SUM(CASE WHEN parent_n=0 THEN 1 ELSE 0 END),0) AS MISSING_PARENT_n,COALESCE(SUM(CASE WHEN parent_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_PARENT_diff,COALESCE(SUM(CASE WHEN order_n=0 THEN 1 ELSE 0 END),0) AS MISSING_ORDER_n,COALESCE(SUM(CASE WHEN order_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_ORDER_diff,COALESCE(SUM(CASE WHEN transaction_n=0 THEN 1 ELSE 0 END),0) AS MISSING_SUCCESS_TRANSACTION_n,COALESCE(SUM(CASE WHEN transaction_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_SUCCESS_TRANSACTION_diff FROM q LIMIT 1;

