l.is_delete,0)=0 AND COALESCE(l.is_cancel,0)=0 LEFT JOIN legacy_c lc ON lc.order_business_no=CONVERT(l.serial_no USING utf8mb4) COLLATE utf8mb4_general_ci WHERE p.id BETWEEN 23 AND 20022 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND p.transaction_mode=1 AND p.sub_type IN (1000,1001,2000,2001,2002,2100,2200,2201) AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NULL THEN 1 ELSE 0 END),0) AS MID_MISSING_n,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NULL THEN ABS(transaction_amount) ELSE 0 END),0) AS MID_MISSING_diff,COALESCE(SUM(CASE WHEN middle_no IS NOT NULL AND ((status=4 AND middle_status<>4) OR (status<>4 AND middle_status=4)) THEN 1 ELSE 0 END),0) AS MID_STATUS_n,COALESCE(SUM(CASE WHEN middle_no IS NOT NULL AND ((status=4 AND middle_status<>4) OR (status<>4 AND middle_status=4)) THEN ABS(0) ELSE 0 END),0) AS MID_STATUS_diff,COALESCE(SUM(CASE WHEN status=4 AND middle_status=4 AND NOT(transaction_amount <=> middle_amount) THEN 1 ELSE 0 END),0) AS MID_AMOUNT_n,COALESCE(SUM(CASE WHEN status=4 AND middle_status=4 AND NOT(transaction_amount <=> middle_amount) THEN ABS(transaction_amount-middle_amount) ELSE 0 END),0) AS MID_AMOUNT_diff,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NOT NULL AND pay_serial_no IS NOT NULL AND pay_serial_no COLLATE utf8mb4_0900_ai_ci<>CONVERT(middle_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci THEN 1 ELSE 0 END),0) AS MID_LINK_n,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NOT NULL AND pay_serial_no IS NOT NULL AND pay_serial_no COLLATE utf8mb4_0900_ai_ci<>CONVERT(middle_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci THEN ABS(0) ELSE 0 END),0) AS MID_LINK_diff,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n=0 THEN 1 ELSE 0 END),0) AS CHANNEL_MISSING_n,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n=0 THEN ABS(middle_amount) ELSE 0 END),0) AS CHANNEL_MISSING_diff,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n>0 AND NOT(middle_amount <=> channel_actual) THEN 1 ELSE 0 END),0) AS CHANNEL_AMOUNT_n,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n>0 AND NOT(middle_amount <=> channel_actual) THEN ABS(middle_amount-channel_actual) ELSE 0 END),0) AS CHANNEL_AMOUNT_diff,COALESCE(SUM(CASE WHEN status=4 AND channel_success_n=1 AND NOT(channel <=> success_channel) THEN 1 ELSE 0 END),0) AS CHANNEL_CODE_n,COALESCE(SUM(CASE WHEN status=4 AND channel_success_n=1 AND NOT(channel <=> success_channel) THEN ABS(0) ELSE 0 END),0) AS CHANNEL_CODE_diff FROM q LIMIT 1;

