-- ol_order_remit 1..3254
WITH q AS (SELECT p.id,p.serial_no AS business_key,p.fk_order_no,p.pay_status,p.pay_serial_no,o.id AS payable_id,o.paid_amount,r.id AS remit_id,r.status AS remit_status,r.transaction_amount FROM ol_order.payment_order_batch_audit p LEFT JOIN ol_order.payment_order o ON o.order_no=p.fk_order_no AND COALESCE(o.is_delete,0)=0 AND COALESCE(o.is_cancel,0)=0 LEFT JOIN xxt_pay.remit_order r ON r.serial_no=CONVERT(p.pay_serial_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(r.is_delete,0)=0 AND COALESCE(r.is_cancel,0)=0 WHERE p.id BETWEEN 1 AND 3254 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN payable_id IS NULL THEN 1 ELSE 0 END),0) AS PAYABLE_MISSING_n,COALESCE(SUM(CASE WHEN payable_id IS NULL THEN ABS(0) ELSE 0 END),0) AS PAYABLE_MISSING_diff,COALESCE(SUM(CASE WHEN pay_status='SUCCESS' AND remit_id IS NULL THEN 1 ELSE 0 END),0) AS REMIT_MISSING_n,COALESCE(SUM(CASE WHEN pay_status='SUCCESS' AND remit_id IS NULL THEN ABS(paid_amount) ELSE 0 END),0) AS REMIT_MISSING_diff,COALESCE(SUM(CASE WHEN remit_id IS NOT NULL AND ((pay_status='SUCCESS')<>(remit_status='SUCCESS')) THEN 1 ELSE 0 END),0) AS REMIT_STATUS_n,COALESCE(SUM(CASE WHEN remit_id IS NOT NULL AND ((pay_status='SUCCESS')<>(remit_status='SUCCESS')) THEN ABS(paid_amount) ELSE 0 END),0) AS REMIT_STATUS_diff,COALESCE(SUM(CASE WHEN pay_status='SUCCESS' AND remit_status='SUCCESS' AND NOT(paid_amount <=> transaction_amount) THEN 1 ELSE 0 END),0) AS REMIT_AMOUNT_n,COALESCE(SUM(CASE WHEN pay_status='SUCCESS' AND remit_status='SUCCESS' AND NOT(paid_amount <=> transaction_amount) THEN ABS(paid_amount-transaction_amount) ELSE 0 END),0) AS REMIT_AMOUNT_diff FROM q LIMIT 1;

