-- ol_saps_refund 1..15
WITH q AS (SELECT p.id,p.refund_no AS business_key,p.refund_status,p.apply_refund_amount,p.refunded_amount,(SELECT COALESCE(SUM(d.refund_amount),0) FROM ol_saps.refund_payment_flow d WHERE d.refund_no=p.refund_no AND d.request_status='SUCCESS' AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS flow_amount,(SELECT COUNT(*) FROM ol_saps.refund_payment_flow d WHERE d.refund_no=p.refund_no AND d.request_status='SUCCESS' AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0 AND NOT EXISTS(SELECT 1 FROM ol_saps.customer_order o WHERE o.biz_no=d.request_no AND o.status=4 AND o.sub_type IN (3003,3004,3005) AND COALESCE(o.is_delete,0)=0 AND COALESCE(o.is_cancel,0)=0)) AS missing_order FROM ol_saps.refund_order p WHERE p.id BETWEEN 1 AND 15 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN NOT(refunded_amount <=> flow_amount) THEN 1 ELSE 0 END),0) AS REFUND_FLOW_n,COALESCE(SUM(CASE WHEN NOT(refunded_amount <=> flow_amount) THEN ABS(refunded_amount-flow_amount) ELSE 0 END),0) AS REFUND_FLOW_diff,COALESCE(SUM(CASE WHEN missing_order>0 THEN 1 ELSE 0 END),0) AS REFUND_ORDER_n,COALESCE(SUM(CASE WHEN missing_order>0 THEN ABS(flow_amount) ELSE 0 END),0) AS REFUND_ORDER_diff,COALESCE(SUM(CASE WHEN refund_status='REFUND_SUCCESS' AND NOT(apply_refund_amount <=> refunded_amount) THEN 1 ELSE 0 END),0) AS REFUND_STATUS_n,COALESCE(SUM(CASE WHEN refund_status='REFUND_SUCCESS' AND NOT(apply_refund_amount <=> refunded_amount) THEN ABS(apply_refund_amount-refunded_amount) ELSE 0 END),0) AS REFUND_STATUS_diff FROM q LIMIT 1;

-- lease_finance_remit 2..67
WITH q AS (SELECT p.id,p.payment_no AS business_key,p.payment_result,p.pay_amount,p.payment_serial_no,r.id AS remit_id,r.status AS remit_status,r.transaction_amount FROM lease_finance.payment_order p LEFT JOIN lease_payment.remit_order r ON r.biz_serial_no=p.payment_serial_no COLLATE utf8_general_ci AND COALESCE(r.is_delete,0)=0 AND COALESCE(r.is_cancel,0)=0 WHERE p.id BETWEEN 2 AND 67 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN payment_result=4 AND remit_id IS NULL THEN 1 ELSE 0 END),0) AS REMIT_MISSING_n,COALESCE(SUM(CASE WHEN payment_result=4 AND remit_id IS NULL THEN ABS(pay_amount) ELSE 0 END),0) AS REMIT_MISSING_diff,COALESCE(SUM(CASE WHEN remit_id IS NOT NULL AND ((payment_result=4)<>(remit_status=4)) THEN 1 ELSE 0 END),0) AS REMIT_STATUS_n,COALESCE(SUM(CASE WHEN remit_id IS NOT NULL AND ((payment_result=4)<>(remit_status=4)) THEN ABS(pay_amount) ELSE 0 END),0) AS REMIT_STATUS_diff,COALESCE(SUM(CASE WHEN payment_result=4 AND remit_status=4 AND NOT(pay_amount <=> transaction_amount) THEN 1 ELSE 0 END),0) AS REMIT_AMOUNT_n,COALESCE(SUM(CASE WHEN payment_result=4 AND remit_status=4 AND NOT(pay_amount <=> transaction_amount) THEN ABS(pay_amount-transaction_amount) ELSE 0 END),0) AS REMIT_AMOUNT_diff FROM q LIMIT 1;

-- ol_order_acceptance_slip 1..5533
WITH q AS (SELECT p.id,p.acceptance_payment_slip_no AS business_key,p.acceptance_payment_slip_amount AS expected_amount,(SELECT COUNT(*) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.acceptance_payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n,(SELECT SUM(d.total_amount) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.acceptance_payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_amount FROM ol_order.lease_apply p WHERE p.id BETWEEN 1 AND 5533 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL) AND p.acceptance_payment_slip_amount>0 AND p.service_status>=175) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN generated_n=0 THEN 1 ELSE 0 END),0) AS GENERATION_MISSING_n,COALESCE(SUM(CASE WHEN generated_n=0 THEN ABS(expected_amount) ELSE 0 END),0) AS GENERATION_MISSING_diff,COALESCE(SUM(CASE WHEN generated_n>0 AND NOT(expected_amount <=> generated_amount) THEN 1 ELSE 0 END),0) AS GENERATION_AMOUNT_n,COALESCE(SUM(CASE WHEN generated_n>0 AND NOT(expected_amount <=> generated_amount) THEN ABS(expected_amount-generated_amount) ELSE 0 END),0) AS GENERATION_AMOUNT_diff FROM q LIMIT 1;

