-- lease_saps_statement 6..110
WITH q AS (SELECT p.id,p.statement_no AS business_key,p.tenant_code,p.total_amount,p.paid_amount,p.unpaid_amount,COALESCE(p.red_amount,0) AS red_amount,p.status AS status,(SELECT COUNT(*) FROM lease_saps.statement_resource d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS fee_n,(SELECT COALESCE(SUM(fee_amount),0) FROM lease_saps.statement_resource d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS resource_total,(SELECT COUNT(*) FROM lease_saps.statement_fee_detail d WHERE d.statement_no=p.statement_no AND d.is_delete=0 AND d.is_cancel=0) AS fee_detail_n,(SELECT COALESCE(SUM(total_amount),0) FROM lease_saps.statement_fee_detail d WHERE d.statement_no=p.statement_no AND d.is_delete=0 AND d.is_cancel=0) AS fee_detail_total,NULL AS fee_paid,NULL AS fee_unpaid,(SELECT COALESCE(SUM(trans_amount),0) FROM lease_saps.statement_pay_detail d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS pay_total,(SELECT COUNT(*) FROM lease_saps.statement d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicates FROM lease_saps.statement p WHERE p.id BETWEEN 6 AND 110 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN NOT(total_amount <=> CASE WHEN fee_detail_n>0 THEN fee_detail_total ELSE resource_total END) THEN 1 ELSE 0 END),0) AS TOTAL_DETAILS_n,COALESCE(SUM(CASE WHEN NOT(total_amount <=> CASE WHEN fee_detail_n>0 THEN fee_detail_total ELSE resource_total END) THEN ABS(total_amount-CASE WHEN fee_detail_n>0 THEN fee_detail_total ELSE resource_total END) ELSE 0 END),0) AS TOTAL_DETAILS_diff,COALESCE(SUM(CASE WHEN total_amount<>0 AND fee_n=0 THEN 1 ELSE 0 END),0) AS MISSING_DETAILS_n,COALESCE(SUM(CASE WHEN total_amount<>0 AND fee_n=0 THEN ABS(total_amount) ELSE 0 END),0) AS MISSING_DETAILS_diff,COALESCE(SUM(CASE WHEN ROUND(total_amount,2) <> ROUND(paid_amount+unpaid_amount+red_amount,2) THEN 1 ELSE 0 END),0) AS BALANCE_n,COALESCE(SUM(CASE WHEN ROUND(total_amount,2) <> ROUND(paid_amount+unpaid_amount+red_amount,2) THEN ABS(ROUND(total_amount,2)-ROUND(paid_amount+unpaid_amount+red_amount,2)) ELSE 0 END),0) AS BALANCE_diff,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> pay_total) THEN 1 ELSE 0 END),0) AS PAID_SETTLEMENT_n,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> pay_total) THEN ABS(paid_amount-pay_total) ELSE 0 END),0) AS PAID_SETTLEMENT_diff,COALESCE(SUM(CASE WHEN status=1 AND (unpaid_amount IS NULL OR unpaid_amount<>0) THEN 1 ELSE 0 END),0) AS SETTLED_UNPAID_n,COALESCE(SUM(CASE WHEN status=1 AND (unpaid_amount IS NULL OR unpaid_amount<>0) THEN ABS(unpaid_amount) ELSE 0 END),0) AS SETTLED_UNPAID_diff,COALESCE(SUM(CASE WHEN duplicates>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicates>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff FROM q LIMIT 1;

