-- ol_order_batch_generation 1..0
WITH q AS (SELECT p.id,p.batch_no AS business_key,p.batch_status,p.payment_slip_amount,p.purchase_price,(SELECT COUNT(*) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS slip_n,(SELECT COUNT(*) FROM ol_order.payment_order d WHERE d.batch_no=p.batch_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS payable_n FROM ol_order.lease_apply_batch p WHERE p.id BETWEEN 1 AND 0 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND p.batch_status>=10 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN payment_slip_amount>0 AND slip_n=0 THEN 1 ELSE 0 END),0) AS SLIP_GENERATION_n,COALESCE(SUM(CASE WHEN payment_slip_amount>0 AND slip_n=0 THEN ABS(payment_slip_amount) ELSE 0 END),0) AS SLIP_GENERATION_diff,COALESCE(SUM(CASE WHEN batch_status=30 AND purchase_price>0 AND payable_n=0 THEN 1 ELSE 0 END),0) AS PAYABLE_GENERATION_n,COALESCE(SUM(CASE WHEN batch_status=30 AND purchase_price>0 AND payable_n=0 THEN ABS(purchase_price) ELSE 0 END),0) AS PAYABLE_GENERATION_diff FROM q LIMIT 1;

