-- lease_saps_bill_generation 1..8700
WITH q AS (SELECT p.id,p.schedule_code AS business_key,p.application_code,p.period,p.repay_total_amount,(SELECT COUNT(*) FROM lease_saps.customer_bill d WHERE d.application_no=CONVERT(p.application_code USING utf8mb4) COLLATE utf8mb4_general_ci AND d.period=p.period AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n,(SELECT COUNT(*) FROM lease_saps.customer_bill d WHERE d.application_no=CONVERT(p.application_code USING utf8mb4) COLLATE utf8mb4_general_ci AND d.pid=CONVERT(p.schedule_code USING utf8mb4) COLLATE utf8mb4_general_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS exact_link_n FROM lease_finance.loan_customer_repayment_schedule p WHERE p.id BETWEEN 1 AND 8700 AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (NULL IS NULL OR p.create_time>=NULL) AND (NULL IS NULL OR p.create_time<NULL) AND p.schedule_class='1' AND EXISTS(SELECT 1 FROM lease_finance.loan_apply a WHERE a.loan_code=p.loan_code AND a.status=360 AND COALESCE(a.is_delete,0)=0 AND COALESCE(a.is_cancel,0)=0)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN generated_n=0 THEN 1 ELSE 0 END),0) AS GENERATION_MISSING_n,COALESCE(SUM(CASE WHEN generated_n=0 THEN ABS(repay_total_amount) ELSE 0 END),0) AS GENERATION_MISSING_diff,COALESCE(SUM(CASE WHEN generated_n>1 THEN 1 ELSE 0 END),0) AS GENERATION_DUPLICATE_n,COALESCE(SUM(CASE WHEN generated_n>1 THEN ABS(0) ELSE 0 END),0) AS GENERATION_DUPLICATE_diff,COALESCE(SUM(CASE WHEN generated_n>0 AND exact_link_n=0 THEN 1 ELSE 0 END),0) AS PLAN_LINK_n,COALESCE(SUM(CASE WHEN generated_n>0 AND exact_link_n=0 THEN ABS(0) ELSE 0 END),0) AS PLAN_LINK_diff FROM q LIMIT 1;

